module radix2_div(
    input clk, input rst, input sign, input [7:0] dividend, input [7:0] divisor, input opn_valid, 
    output reg res_valid, output reg [15:0] result
);
// Internal signals
reg [7:0] dividend_reg;
reg [7:0] divisor_reg;
reg [15:0] SR;
reg [3:0] cnt;
reg [3:0] start_cnt;
reg [7:0] NEG_DIVISOR;
reg [15:0] temp;
wire [8:0] sub_result = {1'b0,SR[15:8]} - {1'b0,NEG_DIVISOR};
wire carry_out = ~sub_result[8];
wire [15:0] mux_out = carry_out ? ({1'b0,sub_result[7:0],SR[7:0]} << 1) | (carry_out << 8) :
                                                     ({1'b0,SR[15:8],SR[7:0]} << 1);
// Sequential logic
always @(posedge clk or negedge rst) begin
    if (!rst) begin
        cnt <= 4'd0;
        start_cnt <= 4'd0;
        SR <= 16'd0;
        temp <= 16'd0;
    end else if (opn_valid && !res_valid) begin
        dividend_reg <= (sign ? (~dividend + 1'b1) : dividend);
        divisor_reg <= (sign ? (~divisor + 1'b1) : divisor);
        SR <= {dividend_reg, 1'b0}; // Shift dividend left by 1 bit
        NEG_DIVISOR <= ~(divisor_reg) + 1'b1; // Negate the divisor for subtraction
        cnt <= 4'd1;
        start_cnt <= 4'd1;
    end else if (start_cnt) begin
        if (cnt[3]) begin
            cnt <= 4'd0;
            start_cnt <= 4'd0;
            SR <= mux_out;
        end else begin
            cnt <= cnt + 1'd1;
            SR <= mux_out;
        end
    end
end
// Combinational logic
always @(*) begin
    if (!rst) begin
        res_valid = 1'b0;
        result = 16'd0;
    end else if (!cnt || res_valid) begin
        res_valid = 1'b0;
        result = 16'dz;
    end else begin
        res_valid = 1'b1;
        result = SR;
    end
end
endmodule
